  1	import { describe, expect, it, vi } from "vitest";
  2	import {
  3		persistOpenAiViewSnapshot,
  4		readOpenAiCompatSnapshot,
  5		snapshotCapabilityFromOpenAiGlobals,
  6	} from "./openai-compat";
  7	
  8	describe("ChatGPT MCP app compatibility globals", () => {
  9		it("reads the result snapshot capability from compatibility metadata", () => {
 10			expect(
 11				snapshotCapabilityFromOpenAiGlobals({
 12					toolOutput: {},
 13					toolResponseMetadata: {
 14						mcp_tool_result: {
 15							_meta: {
 16								"lobu/mcp-app-snapshot-capability": "  restore-token  ",
 17							},
 18						},
 19					},
 20				}),
 21			).toBe("restore-token");
 22			expect(
 23				snapshotCapabilityFromOpenAiGlobals({
 24					toolOutput: { structuredContent: {} },
 25				}),
 26			).toBeUndefined();
 27			expect(
 28				snapshotCapabilityFromOpenAiGlobals({
 29					toolOutput: { structuredContent: {}, _meta: {} },
 30				}),
 31			).toBeNull();
 32		});
 33	
 34		it("restores structured content and the hidden approval capability", () => {
 35			expect(
 36				readOpenAiCompatSnapshot({
 37					toolOutput: { title: "Reloaded result", blocks: [] },
 38					toolResponseMetadata: {
 39						mcp_tool_result: {
 40							_meta: { "lobu/approval-capability": "signed-capability" },
 41						},
 42					},
 43				}),
 44			).toEqual({
 45				data: { title: "Reloaded result", blocks: [] },
 46				approvalCapability: "signed-capability",
 47			});
 48		});
 49	
 50		it("accepts the alternate full-result envelope ChatGPT exposes", () => {
 51			expect(
 52				readOpenAiCompatSnapshot({
 53					toolOutput: { rows: [{ row_number: 1 }] },
 54					toolResponseMetadata: {
 55						call_tool_result: {
 56							_meta: { "lobu/approval-capability": "alternate-capability" },
 57						},
 58					},
 59				}),
 60			).toEqual({
 61				data: { rows: [{ row_number: 1 }] },
 62				approvalCapability: "alternate-capability",
 63			});
 64		});
 65	
 66		it("unwraps structured content from a restored full tool result", () => {
 67			expect(
 68				readOpenAiCompatSnapshot({
 69					toolOutput: {
 70						structuredContent: { rows: [{ row_number: 1 }] },
 71						content: [{ type: "text", text: "1 row" }],
 72					},
 73				}),
 74			).toEqual({
 75				data: { rows: [{ row_number: 1 }] },
 76				approvalCapability: null,
 77			});
 78		});
 79	
 80		it("removes approval controls from a full result with no capability", () => {
 81			expect(
 82				readOpenAiCompatSnapshot({
 83					toolOutput: {
 84						structuredContent: {
 85							version: 1,
 86							actions: [
 87								{ id: "approve", tool: "resolve_lobu_approval" },
 88								{ id: "review", href: "https://lobu.ai/runs/42" },
 89							],
 90						},
 91					},
 92				}),
 93			).toEqual({
 94				data: {
 95					version: 1,
 96					actions: [{ id: "review", href: "https://lobu.ai/runs/42" }],
 97				},
 98				approvalCapability: null,
 99			});
100		});
101	
102		it("retains full-result approval controls only with an embedded capability", () => {
103			expect(
104				readOpenAiCompatSnapshot({
105					toolOutput: {
106						structuredContent: {
107							version: 1,
108							actions: [{ id: "approve", tool: "resolve_lobu_approval" }],
109						},
110						_meta: { "lobu/approval-capability": "embedded-capability" },
111					},
112				}),
113			).toEqual({
114				data: {
115					version: 1,
116					actions: [{ id: "approve", tool: "resolve_lobu_approval" }],
117				},
118				approvalCapability: "embedded-capability",
119			});
120		});
121	
122		it("restores a versioned per-widget view snapshot when output is omitted", () => {
123			expect(
124				readOpenAiCompatSnapshot({
125					widgetState: {
126						privateContent: {
127							lobuViewSnapshot: {
128								version: 1,
129								data: { title: "Cached view" },
130							},
131						},
132					},
133				}),
134			).toEqual({
135				data: { title: "Cached view" },
136				approvalCapability: undefined,
137			});
138		});
139	
140		it("lets an explicit output clear override a cached snapshot", () => {
141			expect(
142				readOpenAiCompatSnapshot({
143					toolOutput: null,
144					widgetState: {
145						privateContent: {
146							lobuViewSnapshot: {
147								version: 1,
148								data: { title: "Stale view" },
149							},
150						},
151					},
152				}),
153			).toEqual({ data: null, approvalCapability: undefined });
154		});
155	
156		it("persists only display data while preserving unrelated widget state", () => {
157			const setWidgetState = vi.fn();
158			const globals = {
159				widgetState: {
160					publicContent: { page: 2 },
161					privateContent: { anotherAppKey: "preserved" },
162				},
163				setWidgetState,
164				toolResponseMetadata: {
165					mcp_tool_result: {
166						_meta: { "lobu/approval-capability": "must-not-persist" },
167					},
168				},
169			};
170	
171			expect(
172				persistOpenAiViewSnapshot(globals, { title: "Persisted view" }),
173			).toBe(true);
174			expect(setWidgetState).toHaveBeenCalledWith({
175				publicContent: { page: 2 },
176				privateContent: {
177					anotherAppKey: "preserved",
178					lobuViewSnapshot: {
179						version: 1,
180						data: { title: "Persisted view" },
181					},
182				},
183			});
184			expect(JSON.stringify(setWidgetState.mock.calls)).not.toContain(
185				"must-not-persist",
186			);
187		});
188	
189		it("does not cache capability-gated approval controls", () => {
190			const setWidgetState = vi.fn();
191			expect(
192				persistOpenAiViewSnapshot(
193					{ setWidgetState },
194					{
195						version: 1,
196						actions: [
197							{
198								id: "approve",
199								tool: "resolve_lobu_approval",
200								args: { run_id: 42, decision: "approve" },
201							},
202							{ id: "review", href: "https://lobu.ai/runs/42" },
203						],
204					},
205				),
206			).toBe(true);
207			expect(setWidgetState).toHaveBeenCalledWith({
208				privateContent: {
209					lobuViewSnapshot: {
210						version: 1,
211						data: {
212							version: 1,
213							actions: [{ id: "review", href: "https://lobu.ai/runs/42" }],
214						},
215					},
216				},
217			});
218		});
219	
220		it("does not restore approval controls after explicit metadata loss", () => {
221			expect(
222				readOpenAiCompatSnapshot({
223					toolOutput: {
224						version: 1,
225						actions: [
226							{ id: "approve", tool: "resolve_lobu_approval" },
227							{ id: "review", href: "https://lobu.ai/runs/42" },
228						],
229					},
230					toolResponseMetadata: null,
231				}),
232			).toEqual({
233				data: {
234					version: 1,
235					actions: [{ id: "review", href: "https://lobu.ai/runs/42" }],
236				},
237				approvalCapability: null,
238			});
239		});
240	
241		it("rejects malformed output and unbounded capability values", () => {
242			expect(
243				readOpenAiCompatSnapshot({
244					toolOutput: ["not", "a", "view"],
245					toolResponseMetadata: {
246						mcp_tool_result: {
247							_meta: { "lobu/approval-capability": "x".repeat(4_097) },
248						},
249					},
250				}),
251			).toEqual({ data: null, approvalCapability: null });
252		});
253	
254		it("distinguishes omitted globals from explicit clears", () => {
255			expect(readOpenAiCompatSnapshot({ toolOutput: null })).toEqual({
256				data: null,
257				approvalCapability: undefined,
258			});
259			expect(readOpenAiCompatSnapshot({ toolResponseMetadata: {} })).toEqual({
260				data: undefined,
261				approvalCapability: null,
262			});
263			expect(readOpenAiCompatSnapshot({})).toEqual({
264				data: undefined,
265				approvalCapability: undefined,
266			});
267		});
268	});
  1	type UnknownRecord = Record<string, unknown>;
  2	
  3	const LOBU_VIEW_SNAPSHOT_KEY = "lobuViewSnapshot";
  4	const LOBU_VIEW_SNAPSHOT_VERSION = 1;
  5	
  6	export interface OpenAiCompatSnapshot<T> {
  7		/** `undefined` means the host did not update this global. */
  8		data: T | null | undefined;
  9		/** `undefined` means the host did not update this global. */
 10		approvalCapability: string | null | undefined;
 11	}
