 13	function snapshotCapabilityFromMeta(meta: unknown): string | null {
 14		if (!isStructuredObject(meta)) return null;
 15		const token = meta["lobu/mcp-app-snapshot-capability"];
 16		if (typeof token !== "string") return null;
 17		const normalized = token.trim();
 18		return normalized && normalized.length <= 512 ? normalized : null;
 19	}
 20	
 21	function isStructuredObject(value: unknown): value is UnknownRecord {
 22		return Boolean(value) && typeof value === "object" && !Array.isArray(value);
 23	}
 24	
 25	export function approvalCapabilityFromMeta(meta: unknown): string | null {
 26		if (!isStructuredObject(meta)) return null;
 27		const token = meta["lobu/approval-capability"];
 28		return typeof token === "string" && token.length <= 4_096 ? token : null;
 29	}
 30	
 31	function approvalCapabilityFromResult(result: unknown): string | null {
 32		if (!isStructuredObject(result)) return null;
 33		return approvalCapabilityFromMeta(result._meta);
 34	}
 35	
 36	function snapshotCapabilityFromResult(
 37		result: unknown,
 38	): string | null | undefined {
 39		if (!isStructuredObject(result) || !Object.hasOwn(result, "_meta"))
 40			return undefined;
 41		return snapshotCapabilityFromMeta(result._meta);
 42	}
 43	
 44	/** Read the opaque per-result restore key from ChatGPT compatibility globals. */
 45	export function snapshotCapabilityFromOpenAiGlobals(
 46		globals: unknown,
 47	): string | null | undefined {
 48		if (!isStructuredObject(globals)) return undefined;
 49		const hasToolOutput = Object.hasOwn(globals, "toolOutput");
 50		const hasFullToolResult =
 51			hasToolOutput &&
 52			isStructuredObject(globals.toolOutput) &&
 53			Object.hasOwn(globals.toolOutput, "structuredContent");
 54		const hasToolResponseMetadata = Object.hasOwn(
 55			globals,
 56			"toolResponseMetadata",
 57		);
 58		const metadata = isStructuredObject(globals.toolResponseMetadata)
 59			? globals.toolResponseMetadata
 60			: null;
 61		if (hasToolResponseMetadata) {
 62			return metadata
 63				? (snapshotCapabilityFromResult(metadata.mcp_tool_result) ??
 64						snapshotCapabilityFromResult(metadata.call_tool_result) ??
 65						null)
 66				: null;
 67		}
 68		return hasFullToolResult
 69			? snapshotCapabilityFromResult(globals.toolOutput)
 70			: undefined;
 71	}
 72	
 73	function dataFromToolOutput<T>(toolOutput: unknown): T | null {
 74		if (!isStructuredObject(toolOutput)) return null;
 75		if (Object.hasOwn(toolOutput, "structuredContent")) {
 76			return isStructuredObject(toolOutput.structuredContent)
 77				? (toolOutput.structuredContent as T)
 78				: null;
 79		}
 80		return toolOutput as T;
 81	}
 82	
 83	function dataFromWidgetState<T>(widgetState: unknown): T | null | undefined {
 84		if (!isStructuredObject(widgetState)) return undefined;
 85		const privateContent = widgetState.privateContent;
 86		if (!isStructuredObject(privateContent)) return undefined;
 87		const snapshot = privateContent[LOBU_VIEW_SNAPSHOT_KEY];
 88		if (!isStructuredObject(snapshot)) return undefined;
 89		if (snapshot.version !== LOBU_VIEW_SNAPSHOT_VERSION) return undefined;
 90		return snapshot.data === null
 91			? null
 92			: isStructuredObject(snapshot.data)
 93				? (snapshot.data as T)
 94				: undefined;
 95	}
 96	
 97	function displaySafeSnapshotData<T>(data: T | null): T | null {
 98		if (!isStructuredObject(data) || !Array.isArray(data.actions)) return data;
 99		return {
100			...data,
101			actions: data.actions.filter(
102				(action) =>
103					!isStructuredObject(action) || action.tool !== "resolve_lobu_approval",
104			),
105		} as T;
106	}
107	
108	/**
109	 * Cache the latest server-authored view in ChatGPT's per-widget UI state. The
110	 * snapshot is a display-only reload fallback; a fresh tool result always wins.
111	 * Hidden result metadata is deliberately excluded.
112	 */
113	export function persistOpenAiViewSnapshot<T>(
114		globals: unknown,
115		data: T | null,
116	): boolean {
117		if (!isStructuredObject(globals)) return false;
118		const setWidgetState = globals.setWidgetState;
119		if (typeof setWidgetState !== "function") return false;
120	
121		const widgetState = isStructuredObject(globals.widgetState)
122			? globals.widgetState
123			: {};
124		const privateContent = isStructuredObject(widgetState.privateContent)
125			? widgetState.privateContent
126			: {};
127		const nextWidgetState = {
128			...widgetState,
129			privateContent: {
130				...privateContent,
131				[LOBU_VIEW_SNAPSHOT_KEY]: {
132					version: LOBU_VIEW_SNAPSHOT_VERSION,
133					data: displaySafeSnapshotData(data),
134				},
135			},
136		};
137	
138		try {
139			const result = Reflect.apply(setWidgetState, globals, [nextWidgetState]);
140			if (isStructuredObject(result) && typeof result.catch === "function") {
141				void Reflect.apply(result.catch, result, [() => {}]);
142			}
143			return true;
144		} catch {
145			return false;
146		}
147	}
148	
149	/**
150	 * Read ChatGPT's compatibility globals without making them a dependency of the
151	 * portable MCP Apps bridge. ChatGPT restores these globals for historical
152	 * cards, including after the standard tool-result notification has already
153	 * happened in an earlier page lifetime.
154	 */
155	export function readOpenAiCompatSnapshot<T>(
156		globals: unknown,
157	): OpenAiCompatSnapshot<T> {
158		if (!isStructuredObject(globals)) {
159			return { data: undefined, approvalCapability: undefined };
160		}
161	
162		const hasToolOutput = Object.hasOwn(globals, "toolOutput");
163		const hasFullToolResult =
164			hasToolOutput &&
165			isStructuredObject(globals.toolOutput) &&
166			Object.hasOwn(globals.toolOutput, "structuredContent");
167		const outputData = hasToolOutput
168			? dataFromToolOutput<T>(globals.toolOutput)
169			: dataFromWidgetState<T>(globals.widgetState);
170		const hasToolResponseMetadata = Object.hasOwn(
171			globals,
172			"toolResponseMetadata",
173		);
174		const metadata = isStructuredObject(globals.toolResponseMetadata)
175			? globals.toolResponseMetadata
176			: null;
177		const approvalCapability = hasToolResponseMetadata
178			? metadata
179				? (approvalCapabilityFromResult(metadata.mcp_tool_result) ??
180					approvalCapabilityFromResult(metadata.call_tool_result))
181				: null
182			: hasFullToolResult
183				? approvalCapabilityFromResult(globals.toolOutput)
184				: undefined;
185		const data =
186			hasToolOutput && approvalCapability === null
187				? displaySafeSnapshotData(outputData)
188				: outputData;
189	
190		return { data, approvalCapability };
191	}

