	listeners: new Map<string, Set<(params: unknown) => void>>(),
}));

vi.mock("@modelcontextprotocol/ext-apps", () => ({
	App: class {
		addEventListener(name: string, handler: (params: unknown) => void) {
			const handlers = bridge.listeners.get(name) ?? new Set();
			handlers.add(handler);
			bridge.listeners.set(name, handlers);
		}
		removeEventListener(name: string, handler: (params: unknown) => void) {
			bridge.listeners.get(name)?.delete(handler);
		}
		callServerTool = bridge.callServerTool;
		connect = bridge.connect;
		getHostContext() { return { theme: "light", ...bridge.hostContext }; }
		async openLink() { return { isError: false }; }
	},
	PostMessageTransport: class { async close() {} },
}));

type CompatParent = EventTarget & { location: { origin: string }; openai?: unknown };
const originalParentDescriptor = Object.getOwnPropertyDescriptor(window, "parent");
const originalOpenAiDescriptor = Object.getOwnPropertyDescriptor(window, "openai");

describe("review cases", () => {
	beforeEach(() => {
		vi.resetModules();
		vi.clearAllMocks();
		bridge.listeners.clear();
		bridge.hostContext = {};
		bridge.connect.mockResolvedValue(undefined);
		bridge.callServerTool.mockResolvedValue({ isError: false });
	});
	afterEach(() => {
		if (originalParentDescriptor) Object.defineProperty(window, "parent", originalParentDescriptor);
		if (originalOpenAiDescriptor) Object.defineProperty(window, "openai", originalOpenAiDescriptor);
		else Reflect.deleteProperty(window, "openai");
	});

	it("uses capability restore data instead of unrelated cached widget data", async () => {
		Object.defineProperty(window, "openai", {
			configurable: true,
			value: { widgetState: { privateContent: { lobuViewSnapshot: { version: 1, data: { title: "Old card" } } } } },
		});
		const parent: CompatParent = Object.assign(new EventTarget(), {
			location: { origin: window.location.origin },
			openai: { toolResponseMetadata: { mcp_tool_result: { _meta: { "lobu/mcp-app-snapshot-capability": "new-card-cap" } } } },
		});
		Object.defineProperty(window, "parent", { configurable: true, value: parent });
