		render(<Provider devMock={{ title: "dev" }}><Probe /></Provider>);
		expect(await screen.findByText("New card")).toBeInTheDocument();
	});

	it("does not attach outer stale approval metadata to inner current output", async () => {
		Object.defineProperty(window, "openai", { configurable: true, value: { toolOutput: { title: "Current card" } } });
		const parent: CompatParent = Object.assign(new EventTarget(), {
			location: { origin: window.location.origin },
			openai: { toolResponseMetadata: { mcp_tool_result: { _meta: { "lobu/approval-capability": "stale-approval" } } } },
		});
		Object.defineProperty(window, "parent", { configurable: true, value: parent });
		const { Provider, useMcpApp } = await import("./host");
