		}
		render(<Provider devMock={{ title: "dev" }}><Probe /></Provider>);
		await waitFor(() => expect(bridge.connect).toHaveBeenCalled());
		fireEvent.click(screen.getByRole("button", { name: "Approve" }));
		await waitFor(() => expect(bridge.callServerTool).toHaveBeenCalled());
		expect(bridge.callServerTool).toHaveBeenLastCalledWith({ name: "resolve_lobu_approval", arguments: {} });
	});
});

